// Brings chalk-talk's engine into the skill — back-of-napkin draws with it, for other purposes than a lesson. From the
// chalk-talk npm package (in tools/node_modules): its build becomes scripts/engine-build.mjs (scripts/build.mjs, ours,
// checks the purpose and hands over), its contract and cheat-sheet examples, the text and recipe references, the player
// page and the Lottie player and pack; the kit's browser and page helpers are copied in by the kit. Mermaid is left out
// (its converter is 4.6 MB): a stub says so. Run: npm run assets. Never edit the generated files by hand.
import { copyFileSync, cpSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { vendor } from 'chalk-talk/kit/tools/vendor.mjs'

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, '..')
const skill = join(root, 'skills/back-of-napkin')
const chalk = join(here, 'node_modules/chalk-talk')
const version = JSON.parse(readFileSync(join(chalk, 'package.json'), 'utf8')).version
const banner = (what) => `// GENERATED by tools/assets.mjs from chalk-talk ${version} (${what}). Do not edit.\n`

mkdirSync(join(skill, 'scripts'), { recursive: true })
mkdirSync(join(skill, 'assets'), { recursive: true })
writeFileSync(join(skill, 'scripts/engine-build.mjs'), banner('its scripts/build.mjs') + readFileSync(join(chalk, 'scripts/build.mjs'), 'utf8').replace(/^#!.*\n/, ''))
copyFileSync(join(chalk, 'scripts/pptx.mjs'), join(skill, 'scripts/pptx.mjs')) // the PowerPoint maker, for --pptx
for (const f of ['contract.mjs', 'syntax.mjs']) writeFileSync(join(skill, 'scripts', f), banner(`its scripts/${f}`) + readFileSync(join(chalk, 'scripts', f), 'utf8'))
writeFileSync(join(skill, 'scripts/mermaid.mjs'), `${banner('a stub')}export async function fromMermaid() {\n  throw new Error('a Mermaid diagram is not drawn by back-of-napkin: write the drawing as a .chalk recipe (chalk-talk draws Mermaid).')\n}\n`)
const kit = vendor(join(skill, 'scripts'), ['browser.mjs', 'page.mjs'])
copyFileSync(join(chalk, 'assets/player.html'), join(skill, 'assets/player.html'))
copyFileSync(join(chalk, 'assets/lottie_light.js'), join(skill, 'assets/lottie_light.js'))
rmSync(join(skill, 'assets/lottie'), { recursive: true, force: true })
cpSync(join(chalk, 'assets/lottie'), join(skill, 'assets/lottie'), { recursive: true })
// The text and recipe references, for a step outside the cheat sheet (a quiz in them is a lesson's: the contract
// refuses it here).
mkdirSync(join(skill, 'references'), { recursive: true })
for (const f of ['text.md', 'recipe.md']) writeFileSync(join(skill, 'references', f), `<!-- GENERATED by tools/assets.mjs from chalk-talk ${version}. Do not edit. -->\n` + readFileSync(join(chalk, 'references', f), 'utf8'))
writeFileSync(join(skill, 'assets/VERSION'), `chalk-talk ${version}\n${kit}\n`)
console.log(`✓ assets from chalk-talk ${version}: the engine's build, contract and player, the Lottie pack`)

// The npm package carries the same command line (npx back-of-napkin …).
for (const d of ['scripts', 'assets']) {
  rmSync(join(root, 'npm', d), { recursive: true, force: true })
  cpSync(join(skill, d), join(root, 'npm', d), { recursive: true })
}
copyFileSync(join(root, 'LICENSE'), join(root, 'npm/LICENSE'))
